#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Duration::new(v, DurationUnit::Year365),
        Duration::from_years365(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Year365),
        Duration::from_base(v).as_years365()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Month30),
        Duration::from_months30(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Month30),
        Duration::from_base(v).as_months30()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Week),
        Duration::from_weeks(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Week),
        Duration::from_base(v).as_weeks()
    );
    assert_eq!(Duration::new(v, DurationUnit::Day), Duration::from_days(v));
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Day),
        Duration::from_base(v).as_days()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Hour),
        Duration::from_hours(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Hour),
        Duration::from_base(v).as_hours()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Minute),
        Duration::from_minutes(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Minute),
        Duration::from_base(v).as_minutes()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Second),
        Duration::from_seconds(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Second),
        Duration::from_base(v).as_seconds()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Picosecond),
        Duration::from_picoseconds(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Picosecond),
        Duration::from_base(v).as_picoseconds()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Nanosecond),
        Duration::from_nanoseconds(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Nanosecond),
        Duration::from_base(v).as_nanoseconds()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Microsecond),
        Duration::from_microseconds(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Microsecond),
        Duration::from_base(v).as_microseconds()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::Millisecond),
        Duration::from_milliseconds(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Millisecond),
        Duration::from_base(v).as_milliseconds()
    );
    assert_eq!(
        Duration::new(v, DurationUnit::JulianYear),
        Duration::from_julian_years(v)
    );
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::JulianYear),
        Duration::from_base(v).as_julian_years()
    );
    assert_eq!(Duration::new(v, DurationUnit::Sol), Duration::from_sols(v));
    assert_eq!(
        Duration::from_base(v).convert_to(DurationUnit::Sol),
        Duration::from_base(v).as_sols()
    );
}

